{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
const mode = args[0]

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(text, field, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function makeBucket(name, capacity, refill, per) {
  return {
    name,
    fresh: () => ({ units: capacity * per, last: null }),
    advance(s, tick) {
      if (s.last !== null) {
        s.units += refill * (tick - s.last)
        if (s.units > capacity * per) s.units = capacity * per
      }
      s.last = tick
    },
    allows: (s) => s.units >= per,
    record(s) { s.units -= per },
  }
}

function makeWindow(name, limit, span) {
  return {
    name,
    fresh: () => ({ ticks: [] }),
    advance(s, tick) { s.ticks = s.ticks.filter((t) => t > tick - span) },
    allows: (s) => BigInt(s.ticks.length) < limit,
    record(s, tick) { s.ticks.push(tick) },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (w.length !== n) {
          throw new Fail(d === 'bucket'
            ? 'expected bucket <name> <capacity> <refill> <per>'
            : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        let p
        if (d === 'bucket') {
          const c = int(w[2], 'capacity', 1)
          const r = int(w[3], 'refill', 0)
          const per = int(w[4], 'per', 1)
          p = makeBucket(w[1], c, r, per)
        } else {
          const l = int(w[2], 'limit', 0)
          const s = int(w[3], 'span', 1)
          p = makeWindow(w[1], l, s)
        }
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], p)
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const ps = w.slice(2).map((n) => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(w[1], ps)
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const t = int(w[1], 'tick', 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && t < lastTick) throw new Fail(`tick ${t} is before tick ${lastTick}`)
        lastTick = t
        events.push({ tick: t, key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }

let out = ''
try {
  const { routes, events } = parse(input)
  const states = new Map()
  const counts = new Map()
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, ps] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, ps }
    }
    let denier = null
    if (best) {
      const ss = best.ps.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, p.fresh())
        const s = states.get(id)
        p.advance(s, tick)
        return s
      })
      for (let i = 0; i < ss.length; i++) {
        if (!best.ps[i].allows(ss[i])) { denier = best.ps[i].name; break }
      }
      if (denier === null) best.ps.forEach((p, i) => p.record(ss[i], tick))
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    if (mode === 'replay') out += `${tick} ${key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
  }
  if (mode === 'summary') {
    for (const k of [...counts.keys()].sort()) out += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
    out += `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
EOF
