      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const x of w.slice(1)) {
        if (!NAME.test(x)) throw new Fail(`error: line ${n}: invalid task name ${x}`)
      }
      for (const x of w.slice(1)) uses.push(x)
      for (const d of w.slice(2)) edges.push([w[1], d])
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const u of uses) if (!tasks.has(u)) throw new Fail(`error: unknown task ${u}`)
  const names = [...tasks.keys()].sort(cmp)
  const deps = new Map(names.map((x) => [x, new Set()]))
  for (const [a, b] of edges) deps.get(a).add(b)
  const sorted = new Map(names.map((x) => [x, [...deps.get(x)].sort(cmp)]))
  return { tasks, names, deps: sorted }
}

function findCycle({ names, deps }) {
  const state = new Map()
  const stack = []
  const visit = (x) => {
    state.set(x, 1)
    stack.push(x)
    for (const d of deps.get(x)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(x, 2)
    return null
  }
  for (const x of names) if (!state.get(x)) {
    const c = visit(x)
    if (c) return c
  }
  return null
}

function timing({ tasks, names, deps }) {
  const info = new Map()
  const calc = (x) => {
    if (info.has(x)) return info.get(x)
    let start = 0n
    let depth = 0
    for (const d of deps.get(x)) {
      const i = calc(d)
      if (i.finish > start) start = i.finish
      if (i.depth + 1 > depth) depth = i.depth + 1
    }
    const r = { start, finish: start + tasks.get(x), depth }
    info.set(x, r)
    return r
  }
  let total = 0n
  for (const x of names) {
    const r = calc(x)
    if (r.finish > total) total = r.finish
  }
  return { info, total }
}

function pack(g, workers) {
  const { tasks, names, deps } = g
  const prio = new Map()
  const rev = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of deps.get(x)) rev.get(d).push(x)
  const pr = (x) => {
    if (prio.has(x)) return prio.get(x)
    let m = 0n
    for (const y of rev.get(x)) {
      const p = pr(y)
      if (p > m) m = p
    }
    prio.set(x, m + tasks.get(x))
    return m + tasks.get(x)
  }
  names.forEach(pr)
  const finish = new Map()
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (finish.size < names.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const x of names) {
        if (finish.has(x)) continue
        if (!deps.get(x).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (best === null || prio.get(x) > prio.get(best)) best = x
      }
      if (best === null) break
      const f = t + tasks.get(best)
      finish.set(best, f)
      freeAt[w] = f
      ran[w].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (finish.size >= names.length) break
    t = freeAt.filter((f) => f > t).reduce((a, b) => (a < b ? a : b))
  }
  const out = ran.map((r, i) => `worker ${i}:${r.map((s) => ' ' + s).join('')}`)
  out.push(`makespan ${makespan}`)
  return out
}

function main() {
  const args = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  const cmd = args[0]
  let workers
  if ((cmd === 'waves' || cmd === 'explain') && args.length === 1) {
    // ok
  } else if (cmd === 'pack' && args.length === 2) {
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else {
    throw new Fail(usage)
  }
  const g = parse(readFileSync(0, 'utf8'))
  const cyc = findCycle(g)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
  const out = []
  if (cmd === 'pack') {
    out.push(...pack(g, workers))
  } else {
    const { info, total } = timing(g)
    if (cmd === 'waves') {
      const waves = []
      for (const x of g.names) (waves[info.get(x).depth] ??= []).push(x)
      waves.forEach((ws, k) => out.push(`wave ${k}: ${ws.join(' ')}`))
    } else {
      for (const x of g.names) {
        const r = info.get(x)
        out.push(`${x} start=${r.start} finish=${r.finish} depth=${r.depth}`)
      }
    }
    out.push(`total ${total}`)
  }
  process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
