const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) fail('error: usage: cli.js replay|summary')
const mode = args[0]

import('node:fs').then(({ readFileSync }) => main(readFileSync(0, 'utf8')))

function main(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null
  const err = (n, r) => fail(`error: line ${n}: ${r}`)
  const num = (n, field, s, least) => {
    if (!UINT.test(s) || BigInt(s) < BigInt(least)) err(n, `${field} must be an integer of at least ${least}`)
    return BigInt(s)
  }
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line[0] === '#') continue
    const w = line.split(/\s+/)
    const d = w[0]
    if (d === 'bucket' || d === 'window') {
      const k = d === 'bucket' ? 5 : 4
      if (w.length !== k) err(n, d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (started) err(n, 'declarations must come before the first event')
      if (!NAME.test(w[1])) err(n, `invalid policy name ${w[1]}`)
      let p
      if (d === 'bucket') {
        const capacity = num(n, 'capacity', w[2], 1)
        const refill = num(n, 'refill', w[3], 0)
        const per = num(n, 'per', w[4], 1)
        p = { type: 'bucket', name: w[1], capacity, refill, per }
      } else {
        const limit = num(n, 'limit', w[2], 0)
        const span = num(n, 'span', w[3], 1)
        p = { type: 'window', name: w[1], limit, span }
      }
      if (policies.has(w[1])) err(n, `policy ${w[1]} is declared twice`)
      policies.set(w[1], p)
    } else if (d === 'route') {
      if (w.length < 3) err(n, 'expected route <prefix> <policy>...')
      if (started) err(n, 'declarations must come before the first event')
      if (!NAME.test(w[1])) err(n, `invalid route prefix ${w[1]}`)
      if (routes.has(w[1])) err(n, `prefix ${w[1]} is routed twice`)
      for (const p of w.slice(2)) {
        if (!NAME.test(p)) err(n, `invalid policy name ${p}`)
        if (!policies.has(p)) err(n, `unknown policy ${p}`)
      }
      routes.set(w[1], w.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (w.length !== 3) err(n, 'expected event <tick> <key>')
      const tick = num(n, 'tick', w[1], 0)
      if (!NAME.test(w[2])) err(n, `invalid key ${w[2]}`)
      if (last !== null && tick < last) err(n, `tick ${tick} is before tick ${last}`)
      last = tick
      started = true
      events.push([tick, w[2]])
    } else err(n, `unknown directive ${d}`)
  }

