const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'e', v: e })
const num = (v) => ({ t: 'n', v })
const bool = (v) => ({ t: 'b', v })
const text = (v) => ({ t: 's', v })

function colOrd(s) {
  return s.length === 1 ? s.charCodeAt(0) - 64 : 26 + (s.charCodeAt(0) - 65) * 26 + (s.charCodeAt(1) - 64)
}
function colName(o) {
  if (o <= 26) return String.fromCharCode(64 + o)
  const k = o - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}
// returns {col,row} or null
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colOrd(m[1].toUpperCase()), row }
}
const keyOf = (c, r) => c * 1000 + r
const nameOf = (c, r) => colName(c) + r

// ---------- parsing input
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const content = s.slice(addr.length).replace(/^[ \t]+/, '')
  const a = parseAddr(addr)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  const k = keyOf(a.col, a.row)
  if (cells.has(k)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr.toUpperCase()} is declared twice\n`)
    process.exit(2)
  }
  cells.set(k, { col: a.col, row: a.row, content })
})

// ---------- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw new Error('syntax') }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'num') return { type: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!peekOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          fail()
        }
      }
      return { type: 'call', name: t.v.toUpperCase(), args }
    }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      const t2 = toks[p++]
      if (peekOp('(')) fail()
      return { type: 'range', a: t.v, b: t2.v }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { type: 'bool', v: true }
    if (u === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', w: t.v }
  }
  try {
    const e = cmp()
    if (p < toks.length) return null
    return e
  } catch {
    return null
  }
}

function misplaced(n, direct = false) {
  switch (n.type) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'un': return misplaced(n.e)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push([c, r])
  return out
}

function collectDeps(n, set) {
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.add(keyOf(a.col, a.row)); break }
    case 'range': { const cs = rangeCells(n); if (cs) for (const [c, r] of cs) set.add(keyOf(c, r)); break }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

// ---------- cells
for (const c of cells.values()) {
  const s = c.content
  if (s[0] === '=') {
    c.ast = parseFormula(s.slice(1))
    c.formula = true
    c.bad = !c.ast || misplaced(c.ast)
  }
}

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

if (mode === 'deps') {
  let out = ''
  for (const c of sorted) {
    out += nameOf(c.col, c.row) + ':'
    if (c.formula && c.ast) {
      const set = new Set()
      collectDeps(c.ast, set)
      for (const k of [...set].sort((a, b) => a - b)) out += ' ' + nameOf(Math.floor(k / 1000), k % 1000)
    }
    out += '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---------- evaluation
const memo = new Map()
const active = new Set()

function literal(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.includes(s)) return err(s)
  return text(s)
}

function cellValue(c, r) {
  const k = keyOf(c, r)
  const cell = cells.get(k)
  if (!cell) return num(0)
  if (memo.has(k)) return memo.get(k)
  if (active.has(k)) return err('#CYCLE!')
  let v
  if (!cell.formula) v = literal(cell.content)
  else if (cell.bad) v = err('#ERR!')
