import { makeAddr } from './sheet.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[-+*\/^=<>(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { type: 'err' }
  let p = 0
  const peekOp = (...ops) => p < toks.length && toks[p].k === 'op' && ops.includes(toks[p].v)
  const bad = () => { throw new SyntaxError('bad') }
  function cmp() {
    let l = add()
    while (peekOp('=', '<>', '<', '<=', '>', '>=')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: add() } }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+', '-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*', '/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-', '+')) { const op = toks[p++].v; return { type: 'un', op, e: unary() } }
    return primary()
  }
  function ref(word) {
    return { type: 'ref', addr: makeAddr(word), word }
  }
  function primary() {
    if (p >= toks.length) bad()
    const t = toks[p++]
    if (t.k === 'num') return { type: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') { const e = cmp(); if (!peekOp(')')) bad(); p++; return { type: 'paren', e } }
      bad()
    }
    const up = t.v.toUpperCase()
    if (peekOp('(')) {
      p++
      const args = []
      if (!peekOp(')')) {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          break
        }
      }
      if (!peekOp(')')) bad()
      p++
      return { type: 'call', name: up, args }
    }
    if (peekOp(':')) {
      if (up === 'TRUE' || up === 'FALSE') bad()
      p++
      if (p >= toks.length || toks[p].k !== 'word') bad()
      const w2 = toks[p++].v
      const u2 = w2.toUpperCase()
      if (u2 === 'TRUE' || u2 === 'FALSE' || peekOp('(')) bad()
      return { type: 'range', a: ref(t.v), b: ref(w2) }
    }
    if (up === 'TRUE') return { type: 'bool', v: true }
    if (up === 'FALSE') return { type: 'bool', v: false }
    return ref(t.v)
  }
  let ast
  try {
    ast = cmp()
    if (p < toks.length) bad()
  } catch (e) {
    if (e instanceof SyntaxError) return { type: 'err' }
    throw e
  }
  if (misplaced(ast, false)) return { type: 'err', ast }
  return ast
}

function children(n) {
  switch (n.type) {
    case 'bin': return [n.l, n.r]
    case 'un': case 'paren': return [n.e]
    case 'call': return n.args
    default: return []
  }
}
function misplaced(n, isArg) {
  if (n.type === 'range') return !isArg
  return children(n).some((c) => misplaced(c, n.type === 'call'))
}

export function collectRefs(ast) {
  const out = new Map()
  const add = (a) => { if (a) out.set(a.col * 1000 + a.row, a) }
  const walk = (n) => {
    if (n.type === 'ref') add(n.addr)
    else if (n.type === 'range') {
      if (n.a.addr && n.b.addr) {
        const [c1, c2] = [n.a.addr.col, n.b.addr.col].sort((x, y) => x - y)
        const [r1, r2] = [n.a.addr.row, n.b.addr.row].sort((x, y) => x - y)
        for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) add({ col: c, row: r })
      }
    } else children(n).forEach(walk)
  }
  if (ast.type === 'err') { if (ast.ast) walk(ast.ast) } else walk(ast)
  return [...out.values()]
}
