class Err { constructor(t) { this.t = t } }
const E = (t) => new Err(t)
const ERRTOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function formatValue(v) {
  if (v instanceof Err) return v.t
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

function literal(c) {
  if (c === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return Number(c)
  if (ERRTOKENS.includes(c)) return E(c)
  return c
}

function toNum(v) {
  if (v instanceof Err) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? x : E('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)
function cmpVals(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 1) {
    const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
    for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
  }
  return a === b ? 0 : a < b ? -1 : 1
}

export function evaluateAll(sheet) {
  const memo = new Map()
  const busy = new Set()
  function cellValue(col, row) {
    const key = col * 1000 + row
    if (memo.has(key)) return memo.get(key)
    const c = sheet.get(key)
    if (!c) return 0
    if (busy.has(key)) return E('#CYCLE!')
    busy.add(key)
    const v = c.ast ? ev(c.ast) : literal(c.content)
    busy.delete(key)
    memo.set(key, v)
    return v
  }
  function rangeValues(n) {
    if (!n.a.addr || !n.b.addr) return [E('#REF!')]
    const [c1, c2] = [n.a.addr.col, n.b.addr.col].sort((x, y) => x - y)
    const [r1, r2] = [n.a.addr.row, n.b.addr.row].sort((x, y) => x - y)
    const out = []
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(cellValue(c, r))
    return out
  }
  function call(n) {
    const name = n.name, args = n.args
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return E('#NAME?')
    if (name === 'IF' ? args.length !== 3 : name === 'ABS' ? args.length !== 1 : args.length < 1) return E('#ERR!')
    if (name === 'IF' || name === 'ABS') {
      const one = (a) => {
        if (a.type !== 'range') return ev(a)
        const vs = rangeValues(a)
        return vs.length === 1 ? vs[0] : E('#ERR!')
      }
      if (name === 'ABS') {
        const x = toNum(one(args[0]))
        return x instanceof Err ? x : Math.abs(x)
      }
      const c = one(args[0])
      if (c instanceof Err) return c
      let t
      if (typeof c === 'boolean') t = c
      else if (typeof c === 'number') t = c !== 0
      else return E('#VALUE!')
      const b = args[t ? 1 : 2]
      return b.type === 'range' ? one(b) : ev(b)
    }
    const vals = []
    for (const a of args) {
      if (a.type === 'range') vals.push(...rangeValues(a))
      else vals.push(ev(a))
    }
    for (const v of vals) if (v instanceof Err) return v
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x instanceof Err) return x
      nums.push(x)
    }
    if (name === 'MIN') return Math.min(...nums)
    if (name === 'MAX') return Math.max(...nums)
    let s = 0
    for (const x of nums) s += x
    if (name === 'AVG') s /= nums.length
    return fin(s)
  }
  function ev(n) {
    switch (n.type) {
      case 'err': return E('#ERR!')
      case 'num': return n.v
      case 'bool': return n.v
      case 'paren': return ev(n.e)
      case 'ref': return n.addr ? cellValue(n.addr.col, n.addr.row) : E('#REF!')
      case 'range': return E('#ERR!')
      case 'call': return call(n)
      case 'un': {
        const x = toNum(ev(n.e))
        if (x instanceof Err) return x
        return n.op === '-' ? -x : x
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
        if (l instanceof Err) return l
        if (r instanceof Err) return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = cmpVals(l, r)
          switch (n.op) {
            case '=': return c === 0
            case '<>': return c !== 0
            case '<': return c < 0
            case '<=': return c <= 0
            case '>': return c > 0
            default: return c >= 0
          }
        }
        const a = toNum(l)
        if (a instanceof Err) return a
        const b = toNum(r)
        if (b instanceof Err) return b
        switch (n.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? E('#DIV/0!') : fin(a / b)
          default: return fin(a ** b)
        }
      }
    }
  }
  return (c) => cellValue(c.col, c.row)
}
