    : String.fromCharCode(64 + Math.floor((a.col - 1) / 26)) + String.fromCharCode(65 + ((a.col - 1) % 26))
  return col + a.row
}

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  throw e
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const sheet = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^[^ \t]*/.exec(line)
    const word = m[0]
    const rest = line.slice(word.length).replace(/^[ \t]+/, '')
    const a = makeAddr(word)
    if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
    const key = sortKey(a)
    if (sheet.has(key)) fail(`error: line ${i + 1}: cell ${word} is declared twice`)
    sheet.set(key, { col: a.col, row: a.row, content: rest })
  })
  return sheet
}
