  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (b[i] === s[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const all = [
  ...changes(base, mine).map(c => ({ ...c, side: 0 })),
  ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
].sort((a, b) => a.bs - b.bs || a.side - b.side)

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
const out = []
const regs = []
let conflict = false
let pos = 0
let k = 0
