import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // digit run with underscores only between two digits of the radix
  const run = (ok) => {
    let s = ''
    while (i < n) {
      if (ok(cs[i])) s += adv()
      else if (cs[i] === '_' && s !== '' && ok(cs[i - 1]) && ok(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const p = (cs[i + 1] || '').toLowerCase()
      const radix = c === '0' ? { x: isHex, b: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d !== undefined }[p] : undefined
      if (radix) {
        s += adv(); s += adv()
        const d = run(radix)
        s += d
        if (d === '') {
          while (isIdPart(cs[i])) s += adv()
          throw new ScanError(sl, sc, `invalid number ${s}`)
        }
      } else {
        s += run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); s += run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { s += adv(); s += run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { s += adv(); s += adv(); s += run(isDigit) }
        }
      }
      if (isIdPart(cs[i])) {
        while (isIdPart(cs[i])) s += adv()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      tokens.push([sl, sc, 'number', s])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '"') { adv(); break }
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          v += String.fromCharCode(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw bad()
          while (i <= j) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else throw bad()
      }
      tokens.push([sl, sc, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (cs[i + 1] || '')
    const p = PUNCT.find((q) => (q.length === 2 ? q === two : q === c))
    if (p) {
      for (let k = 0; k < p.length; k++) adv()
      tokens.push([sl, sc, 'punct', p])
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
try {
  const toks = scan(input)
  let out = ''
  if (args[0] === 'tokens') {
    for (const [l, c, k, b] of toks) out += `${l}:${c} ${k} ${b}\n`
  } else {
    for (const k of KINDS) out += `${k} ${toks.filter((t) => t[2] === k).length}\n`
    out += `total ${toks.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
EOF
